SELECT id, symbol, price, UNIX_TIMESTAMP(observed_at) AS obs_epoch, UNIX_TIMESTAMP(created_at) AS created_epoch, ROUND(UNIX_TIMESTAMP(created_at)-UNIX_TIMESTAMP(observed_at),3) AS ingest_lag_s, source, delivery_status, outcome_reason FROM crypto_ai.market_price_event WHERE id IN (1761043,1761095,1788491,1789382,1789409,1862196,1862211,1924096,1924247,1975437,1975516) OR (symbol='EGLDUSDT' AND observed_at BETWEEN FROM_UNIXTIME(1791741299) AND FROM_UNIXTIME(1791741301)) OR (symbol='XRPUSDT' AND observed_at BETWEEN FROM_UNIXTIME(1791761699) AND FROM_UNIXTIME(1791761701)) OR (symbol='DOGEUSDT' AND observed_at BETWEEN FROM_UNIXTIME(1791766922) AND FROM_UNIXTIME(1791766923)) OR (symbol='SHIBUSDT' AND observed_at BETWEEN FROM_UNIXTIME(1791776161) AND FROM_UNIXTIME(1791776162)) OR (symbol='ACEUSDT' AND observed_at BETWEEN FROM_UNIXTIME(1791788222) AND FROM_UNIXTIME(1791788223)) ORDER BY symbol, observed_at LIMIT 40;